pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address alice, address bob, uint8 whichFirst) public {
        // Wide admissible domain: amounts not zero, alice != bob, and alice != address(0), bob != address(0)
        vm.assume(alice != bob);
        vm.assume(alice != address(0));
        vm.assume(bob != address(0));
        amount1 = bound(amount1, 1, 1e36);
        amount2 = bound(amount2, 1, 1e36);

        // Track total added per account
        mapping(address => uint) memory added;

        // alice adds amount1
        vm.deal(alice, amount1);
        vm.prank(alice);
        c.addToBalance{value: amount1}();
        added[alice] = amount1;

        // bob adds amount2
        vm.deal(bob, amount2);
        vm.prank(bob);
        c.addToBalance{value: amount2}();
        added[bob] = amount2;

        // Withdrawal order chosen by fuzzer
        if (whichFirst % 2 == 0) {
            vm.prank(alice);
            c.withdrawBalance();
            vm.prank(bob);
            c.withdrawBalance();
        } else {
            vm.prank(bob);
            c.withdrawBalance();
            vm.prank(alice);
            c.withdrawBalance();
        }

        // General invariant: sum of all user balances still stored in contract
        // equals (total added - total withdrawn). Since withdrawBalance zeros the user's balance
        // and sends it, the remaining contract balance should equal the sum of user balances
        // of users who have not withdrawn.
        // However for simplicity, the invariant: total balance of alice + bob after the scenario
        // equals the total added minus what each withdrew.
        // Since all withdrew, all balances should be zero, and contract balance should be zero.
        // But with buggy addToBalance, the second addition overwrites the first, so total added
        // is not tracked correctly. We assert that the sum of remaining balances of alice and bob
        // plus address(c).balance equals total added.
        uint256 totalAdded = added[alice] + added[bob];
        uint256 remainingAlice = c.getBalance(alice);
        uint256 remainingBob = c.getBalance(bob);
        uint256 contractBal = address(c).balance;

        // For correct version: after both withdraw, remaining=0, contractBal=0, totalAdded = amount1+amount2.
        // But if addToBalance wiped alice's balance when bob added, totalAdded is wrong relative to actual Ether in.
        // The invariant: totalAdded == remainingAlice + remainingBob + contractBal
        assertTrue(totalAdded == remainingAlice + remainingBob + contractBal);
    }
}

