// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        // Re-entrant attacker that calls addToBalance again on receive
        ReEntrant attacker = new ReEntrant(c);
        // Fund the attacker
        vm.deal(address(attacker), amount);
        // Attacker triggers addToBalance, which will overflow userBalance for itself in the buggy version
        vm.prank(address(attacker));
        attacker.attack{value: amount}();
        // Invariant: sum of all userBalances (attacker + actor) must equal address(c).balance
        uint256 sum = c.getBalance(address(attacker)) + c.getBalance(actor);
        assertTrue(sum == address(c).balance);
    }
}

contract ReEntrant {
    C public target;
    bool private locked;

    constructor(C _target) {
        target = _target;
    }

    function attack() public payable {
        target.addToBalance{value: msg.value}();
        // Attempt withdrawal to trigger receive callback; if balance is non-zero, withdrawBalance will send Ether back
        // This re-enters our receive() which calls addToBalance again (with 0 value) to cause overflow in buggy version
        if (address(target).balance >= msg.value) {
            target.withdrawBalance();
        }
    }

    receive() external payable {
        if (!locked) {
            locked = true;
            // Re-enter addToBalance with zero value to trigger overflow accumulation
            target.addToBalance();
            locked = false;
        }
    }
}
